// Selects the industry pack the site runs on: industry-packs/<name>/ is mirrored into industry/, where the
// code reads it (the @aihot/industry workspace). A pack is edited only in industry-packs/; industry/ is
// generated by this step and checked in as the manufacturing pack, which CI checks. industry/package.json,
// tsconfig.json and README.md belong to the framework, not to a pack, and stay as they are.
//   node scripts/select-industry.ts [name]           no name: INDUSTRY_PACK, else manufacturing
//   node scripts/select-industry.ts --check <name>   fails unless industry/ is that pack, byte for byte
// Only node: imports, so it runs before npm ci (CI) and in the image build (Dockerfile).
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, rmdirSync, rmSync } from "node:fs";
import path from "node:path";

export const DEFAULT_PACK = "manufacturing";
/** The framework's own files in industry/: kept on every selection, and never part of a pack. */
const FRAMEWORK_FILES = new Set(["package.json", "tsconfig.json", "README.md"]);
/** Never part of a pack, wherever they turn up (Finder's folder settings, a stray install). */
const IGNORED = new Set([".DS_Store", "node_modules"]);

const ROOT = path.resolve(import.meta.dirname, "..");

/** The packs there are: the directories of industry-packs/. */
export function packNames(root = ROOT): string[] {
  const dir = path.join(root, "industry-packs");
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
}

function packDir(name: string, root: string): string {
  const names = packNames(root);
  if (!names.includes(name)) {
    const choices = names.length ? names.join("、") : "（industry-packs/ 下还没有行业包）";
    throw new Error(`${name ? `没有叫“${name}”的行业包` : "没有给行业包名字"}。可选：${choices}`);
  }
  return path.join(root, "industry-packs", name);
}

/** Every file under dir as a relative path, without the ignored names and, at the top, `skip`. */
function filesUnder(dir: string, skip: ReadonlySet<string> = new Set(), prefix = ""): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .filter((d) => !IGNORED.has(d.name) && !(prefix === "" && skip.has(d.name)))
    .flatMap((d) => d.isDirectory() ? filesUnder(path.join(dir, d.name), skip, `${prefix}${d.name}/`) : [`${prefix}${d.name}`])
    .sort();
}

/** How industry/ differs from the pack: files missing or different, and files the pack does not have. */
function drift(name: string, root: string) {
  const from = packDir(name, root);
  const to = path.join(root, "industry");
  const packFiles = filesUnder(from);
  const clash = packFiles.filter((f) => FRAMEWORK_FILES.has(f));
  if (clash.length) throw new Error(`industry-packs/${name}/ 里不能有 ${clash.join("、")}：这是 industry/ 自己的框架文件，不随行业包走`);
  const present = new Set(filesUnder(to, FRAMEWORK_FILES));
  const inPack = new Set(packFiles);
  const changed = packFiles.filter((f) => !present.has(f) || !readFileSync(path.join(from, f)).equals(readFileSync(path.join(to, f))));
  const extra = [...present].filter((f) => !inPack.has(f));
  return { from, to, changed, extra };
}

/** Removes the empty directories under dir (not dir itself). */
function pruneEmpty(dir: string): void {
  for (const d of readdirSync(dir, { withFileTypes: true })) {
    if (!d.isDirectory() || IGNORED.has(d.name)) continue;
    const sub = path.join(dir, d.name);
    pruneEmpty(sub);
    if (readdirSync(sub).length === 0) rmdirSync(sub);
  }
}

/** Mirrors the pack into industry/, writing only what differs, so selecting the pack already there is a no-op. */
export function selectPack(name: string, root = ROOT): { changed: number; removed: number } {
  const { from, to, changed, extra } = drift(name, root);
  for (const f of changed) {
    mkdirSync(path.dirname(path.join(to, f)), { recursive: true });
    copyFileSync(path.join(from, f), path.join(to, f));
  }
  for (const f of extra) rmSync(path.join(to, f));
  if (extra.length) pruneEmpty(to);
  return { changed: changed.length, removed: extra.length };
}

/** What keeps industry/ from being the pack; empty when it is. */
export function checkPack(name: string, root = ROOT): string[] {
  const { changed, extra } = drift(name, root);
  return [...changed.map((f) => `缺少或不同：${f}`), ...extra.map((f) => `行业包里没有：${f}`)];
}

/**
 * The pack industry/ holds. Throws when it is none of them: edited by hand, or a pack changed since it
 * was selected. Inside the image there is no industry-packs/ to compare against (the build keeps the
 * selected pack only), so the name is the one the build recorded in INDUSTRY_PACK.
 */
export function selectedPack(root = ROOT): string {
  if (packNames(root).length === 0) return process.env.INDUSTRY_PACK || DEFAULT_PACK;
  const name = packNames(root).find((n) => checkPack(n, root).length === 0);
  if (!name) throw new Error("industry/ 和 industry-packs/ 里的行业包都对不上。行业包只在 industry-packs/ 里改，改完运行 npm run industry 重新选一次。");
  return name;
}

if (import.meta.main) {
  const args = process.argv.slice(2);
  try {
    if (args[0] === "--check") {
      const name = args[1] ?? "";
      const problems = checkPack(name);
      if (problems.length) {
        console.error(`industry/ 不是行业包 ${name}：\n  ${problems.join("\n  ")}\n行业包只在 industry-packs/ 里改，改完运行 npm run industry 重新选一次。`);
        process.exit(1);
      }
      console.log(`industry/ 就是行业包 ${name}`);
    } else {
      const name = args.length ? args[0]! : process.env.INDUSTRY_PACK || DEFAULT_PACK;
      const { changed, removed } = selectPack(name);
      console.log(changed || removed ? `行业包 ${name}：industry/ 写入 ${changed} 个文件，删除 ${removed} 个` : `行业包 ${name}：industry/ 已经是它`);
    }
  } catch (error) {
    console.error((error as Error).message);
    process.exit(1);
  }
}
